"use client"

import type { ReactNode } from "react"
import { useSelector } from "@tanstack/react-form"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import {
  fieldErrorMessage,
  isFieldLevelErrorMap,
} from "@/hoogin/ui/form.utils"

type FormStateLike = {
  canSubmit: boolean
  isSubmitting: boolean
  errors: readonly unknown[]
}

type FormStoreLike = {
  get: () => FormStateLike
  subscribe: (
    listener: (value: FormStateLike) => void
  ) => { unsubscribe: () => void }
}

export type FormApiLike = {
  store: FormStoreLike
  handleSubmit: () => Promise<void>
  reset: () => void
}

export function Form({
  form,
  className,
  children,
}: {
  form: FormApiLike
  className?: string
  children?: ReactNode
}) {
  return (
    <form
      noValidate
      onSubmit={(event) => {
        event.preventDefault()
        event.stopPropagation()
        void form.handleSubmit()
      }}
      className={className}
    >
      {children}
    </form>
  )
}

export function FormHeader({
  title,
  description,
  className,
}: {
  title?: ReactNode
  description?: ReactNode
  className?: string
}) {
  return (
    <header className={cn("space-y-1", className)}>
      {title ? (
        <h2 className="font-heading text-base font-medium">{title}</h2>
      ) : null}
      {description ? (
        <p className="text-sm text-muted-foreground">{description}</p>
      ) : null}
    </header>
  )
}

export function FormBody({
  className,
  children,
}: {
  className?: string
  children?: ReactNode
}) {
  return <div className={cn("flex flex-col gap-4", className)}>{children}</div>
}

export function FormFooter({
  form,
  onCancel,
  cancelLabel = "Cancel",
  submitLabel = "Save",
  resetLabel = "Reset",
  showReset = true,
  readOnly = false,
  showActions = true,
  className,
}: {
  form: FormApiLike
  onCancel: () => void
  cancelLabel?: string
  submitLabel?: string
  resetLabel?: string
  showReset?: boolean
  readOnly?: boolean
  showActions?: boolean
  className?: string
}) {
  const canSubmit = useSelector(form.store, (state) => state.canSubmit)
  const isSubmitting = useSelector(form.store, (state) => state.isSubmitting)

  if (!showActions) return null

  return (
    <footer className={cn("mt-2 flex justify-end gap-2", className)}>
      <Button type="button" variant="outline" onClick={onCancel}>
        {readOnly ? "Close" : cancelLabel}
      </Button>
      {!readOnly ? (
        <>
          {showReset ? (
            <Button type="button" variant="ghost" onClick={() => form.reset()}>
              {resetLabel}
            </Button>
          ) : null}
          <Button type="submit" disabled={!canSubmit || isSubmitting}>
            {isSubmitting ? "Saving..." : submitLabel}
          </Button>
        </>
      ) : null}
    </footer>
  )
}

const EMPTY_STORE: FormStoreLike = {
  get: () => ({
    canSubmit: false,
    isSubmitting: false,
    errors: [],
  }),
  subscribe: () => ({ unsubscribe: () => {} }),
}

export function FormError({
  form,
  error,
  className,
}: {
  form?: FormApiLike
  error?: string | null
  className?: string
}) {
  const formErrors = useSelector(form?.store ?? EMPTY_STORE, (state) =>
    state.errors
      .filter((fieldError) => !isFieldLevelErrorMap(fieldError))
      .map(fieldErrorMessage)
      .filter(Boolean)
      .join("\n")
  )

  const messages = [error, formErrors].filter(
    (message): message is string => Boolean(message)
  )
  if (messages.length === 0) return null

  return (
    <p className={cn("text-sm text-destructive", className)}>
      {messages.join(", ")}
    </p>
  )
}

import type { ReactNode } from "react"
import {
  type DeepKeys,
  type DeepValue,
  type FieldAsyncValidateOrFn,
  type FieldValidateOrFn,
  type FieldValidators,
  type FormAsyncValidateOrFn,
  type FormValidateOrFn,
  type ReactFormExtendedApi,
} from "@tanstack/react-form"

import { cn } from "@/lib/utils"
import { fieldErrorMessage } from "@/hoogin/ui/form.utils"

export type FormFieldApi<TValue> = {
  name: string
  handleChange: (value: TValue) => void
  handleBlur: () => void
  invalid: boolean
  state: {
    value: TValue
    meta: {
      isTouched: boolean
      errors: readonly unknown[]
    }
  }
}

type AnyFormApi<TFormData> = ReactFormExtendedApi<
  TFormData,
  undefined | FormValidateOrFn<TFormData>,
  undefined | FormValidateOrFn<TFormData>,
  undefined | FormAsyncValidateOrFn<TFormData>,
  undefined | FormValidateOrFn<TFormData>,
  undefined | FormAsyncValidateOrFn<TFormData>,
  undefined | FormValidateOrFn<TFormData>,
  undefined | FormAsyncValidateOrFn<TFormData>,
  undefined | FormValidateOrFn<TFormData>,
  undefined | FormAsyncValidateOrFn<TFormData>,
  undefined | FormAsyncValidateOrFn<TFormData>,
  unknown
>

export type KeysOfType<TFormData, TValue> = DeepKeys<TFormData> & {
  [K in DeepKeys<TFormData>]: DeepValue<TFormData, K> extends TValue
    ? K
    : never
}[DeepKeys<TFormData>]

type FormFieldValidators<
  TFormData,
  TName extends DeepKeys<TFormData>,
  TData extends DeepValue<TFormData, TName>,
> = FieldValidators<
  TFormData,
  TName,
  TData,
  undefined | FieldValidateOrFn<TFormData, TName, TData>,
  undefined | FieldValidateOrFn<TFormData, TName, TData>,
  undefined | FieldAsyncValidateOrFn<TFormData, TName, TData>,
  undefined | FieldValidateOrFn<TFormData, TName, TData>,
  undefined | FieldAsyncValidateOrFn<TFormData, TName, TData>,
  undefined | FieldValidateOrFn<TFormData, TName, TData>,
  undefined | FieldAsyncValidateOrFn<TFormData, TName, TData>,
  undefined | FieldValidateOrFn<TFormData, TName, TData>,
  undefined | FieldAsyncValidateOrFn<TFormData, TName, TData>
>

export type FormFieldProps<
  TFormData,
  TName extends DeepKeys<TFormData>,
> = {
  form: AnyFormApi<TFormData>
  name: TName
  label?: string
  description?: string
  required?: boolean
  validators?: FormFieldValidators<TFormData, TName, DeepValue<TFormData, TName>>
  className?: string
  children: (field: FormFieldApi<DeepValue<TFormData, TName>>) => ReactNode
}

export function FormField<TFormData, TName extends DeepKeys<TFormData>>({
  form,
  name,
  label,
  description,
  required = false,
  validators,
  className,
  children,
}: FormFieldProps<TFormData, TName>) {
  return (
    <form.Field name={name} validators={validators}>
      {(field) => {
        const messages = field.state.meta.isTouched
          ? field.state.meta.errors.map(fieldErrorMessage)
          : []
        return (
          <div className={cn("flex flex-col gap-1.5", className)}>
            {label ? (
              <label htmlFor={name} id={`${name}-label`} className="text-sm font-medium">
                {label}
                {required ? <span> *</span> : null}
              </label>
            ) : null}
            {children({
              name: field.name,
              handleChange: field.handleChange,
              handleBlur: field.handleBlur,
              invalid:
                field.state.meta.isTouched && field.state.meta.errors.length > 0,
              state: {
                value: field.state.value,
                meta: {
                  isTouched: field.state.meta.isTouched,
                  errors: field.state.meta.errors,
                },
              },
            })}
            {description ? (
              <p className="text-sm text-muted-foreground">{description}</p>
            ) : null}
            {messages.length > 0 ? (
              <p
                id={`${name}-error`}
                role="alert"
                className="text-sm text-destructive"
              >
                {messages.join(", ")}
              </p>
            ) : null}
          </div>
        )
      }}
    </form.Field>
  )
}

export function fieldErrorMessage(error: unknown): string {
  if (typeof error === "string") return error
  if (typeof error === "object" && error !== null && "message" in error) {
    const message = (error as { message: unknown }).message
    if (typeof message === "string") return message
    if (Array.isArray(message)) return message.map(fieldErrorMessage).join(", ")
  }
  return "Invalid value"
}

export function isRequiredField(schema: { isOptional: () => boolean }): boolean {
  return !schema.isOptional()
}

export function isFieldLevelErrorMap(error: unknown): boolean {
  if (typeof error !== "object" || error === null) return false
  if (Array.isArray(error) || "message" in error) return false
  const values = Object.values(error)
  if (values.length === 0) return false
  return values.every((value) => Array.isArray(value) && value.length > 0)
}

import { Square, SquareCheck } from "lucide-react";

export function checkBoxFormatter(value: boolean | undefined) {
    return value ? <SquareCheck /> : <Square />;
}

export function currencyFormatter(value: number, symbol?: string) {
    const currencySymbol = symbol ?? import.meta.env.VITE_CURRENCY_SYMBOL ?? "€";
    return `${currencySymbol} ${(value / 100).toFixed(2)}`;
}

export function minutesFormatter(value: number) {
    const hours = Math.floor(value / 60);
    const minutes = value % 60;

    if (hours === 0) {
        return `${minutes}m`;
    }
    return `${hours}h ${minutes}m`;
}

export function nationalNumberFormatter(value: string) {
    if (!value || value.trim().length == 0) return '';

    const formattedString = value.slice(0, 2) + '.' + value.slice(2, 4) + '.' + value.slice(4, 6) + '-' + value.slice(6, 9) + '.' + value.slice(9);
    return formattedString;
}

export function dateFormatter(value: string) {
    const format = import.meta.env.VITE_DATE_FORMAT ?? "YYYY/MM/DD";
    return formatDate(new Date(value), format);
}

function formatDate(date: Date, format: string) {
    const year = String(date.getFullYear());
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");

    return format
        .replace("YYYY", year)
        .replace("MM", month)
        .replace("DD", day);
}

import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
